      flex: 1;
      position: relative;
      display: flex;
      align-items: center;
      border-right: 1px solid var(--gray-100);
    }
    .search-field:last-of-type { border-right: none; }
    .search-field-icon {
      position: absolute;
      left: 16px;
      color: var(--navy);
      pointer-events: none;
      flex-shrink: 0;
    }
    .search-field-icon svg { width: 18px; height: 18px; }
    .search-input, .search-select {
      width: 100%;
      padding: 16px 16px 16px 44px;
      font-family: inherit;
      font-size: 14px;
      font-weight: 500;
      color: var(--text);
      background: transparent;
      border: none;
      outline: none;
      border-radius: var(--radius-lg);
    }
    .search-input::placeholder, .search-select option[disabled] { color: var(--text-muted); }
    .search-select { appearance: none; cursor: pointer; }
    .search-select-arrow {
      position: absolute;
      right: 14px;
      color: var(--gray-400);
      pointer-events: none;
    }
    .search-btn {
      padding: 14px 28px;
      background: var(--navy);
      color: white;
      border-radius: var(--radius-lg);
      font-size: 15px;
      font-weight: 700;
      display: flex;
      align-items: center;
      gap: 8px;
      transition: background .2s, transform .2s;
      white-space: nowrap;
    }
    .search-btn:hover { background: var(--navy-light); transform: scale(1.02); }
    .search-btn svg { width: 18px; height: 18px; }

    /* Autocomplete dropdown */
    .autocomplete-dropdown {
      display: none;
      position: absolute;
      top: calc(100% + 8px);
      left: -8px;
      right: -8px;
      background: white;
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-lg);
      border: 1px solid var(--gray-100);
      overflow: hidden;
      z-index: 50;
      animation: slideDown .15s ease;
    }
    .autocomplete-dropdown.open { display: block; }
    .autocomplete-section-label {
      padding: 10px 16px 6px;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: .08em;
      text-transform: uppercase;
      color: var(--text-muted);
    }
    .autocomplete-item {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 10px 16px;
      font-size: 14px;
      font-weight: 500;
      color: var(--text);
      cursor: pointer;
      transition: background .12s;
    }
    .autocomplete-item:hover, .autocomplete-item.selected { background: var(--gray-50); }
    .autocomplete-item-icon {
      width: 32px; height: 32px;
      border-radius: 8px;
      background: var(--gray-50);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      font-size: 16px;
    }
    .autocomplete-item-sub {
      font-size: 12px;
      color: var(--text-muted);
      font-weight: 400;
    }

    /* Trust row */
    .hero-trust {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 24px;
      margin-top: 28px;
      flex-wrap: wrap;
    }
    .hero-trust-item {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 13px;
      color: rgba(255,255,255,.7);
      font-weight: 500;
    }
    .hero-trust-item svg { width: 16px; height: 16px; color: var(--yellow); }

    /* ═══════════════════════════════════════
       STATS BAR
    ═══════════════════════════════════════ */
    .stats-bar {
      background: var(--off-white);
      border-bottom: 1px solid var(--gray-100);
    }
    .stats-inner {
      display: flex;
      align-items: stretch;
      justify-content: space-around;
      padding: 32px 0;
    }
    .stat-item {
      text-align: center;
      padding: 0 24px;
      position: relative;
    }
    .stat-item + .stat-item::before {
      content: '';
      position: absolute;
      left: 0;
      top: 10%;
      height: 80%;
      width: 1px;
      background: var(--gray-100);
    }
    .stat-number {
      font-size: clamp(26px, 3.5vw, 40px);
      font-weight: 800;
      color: var(--navy-dark);
      letter-spacing: -.03em;
      line-height: 1;
      margin-bottom: 6px;
    }
    .stat-number span { color: var(--navy); }
    .stat-label {
      font-size: 13px;
      color: var(--text-muted);
      font-weight: 500;
      line-height: 1.4;
    }
    .stat-icon {
      width: 36px; height: 36px;
      border-radius: 10px;
      background: rgba(27,20,100,.08);
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 10px;
    }
    .stat-icon svg { width: 18px; height: 18px; color: var(--navy); }

    /* ═══════════════════════════════════════
       SPECIALTIES
    ═══════════════════════════════════════ */
    .specialties { background: white; }
    .specialties-header {
      text-align: center;
      margin-bottom: 52px;
    }
    .specialties-grid {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 16px;
    }
    .specialty-card {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 14px;
      padding: 28px 16px;
      background: white;
      border: 1.5px solid var(--gray-100);
      border-radius: var(--radius-lg);
      cursor: pointer;
      transition: all .2s ease;
      text-align: center;
      position: relative;
      overflow: hidden;
    }
    .specialty-card::before {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(135deg, rgba(27,20,100,.04), transparent);
      opacity: 0;
      transition: opacity .2s;
    }
    .specialty-card:hover {
      border-color: var(--navy);
      box-shadow: var(--shadow-md);
      transform: translateY(-4px);
    }
    .specialty-card:hover::before { opacity: 1; }
    .specialty-icon {
      width: 60px; height: 60px;
      border-radius: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 28px;
      transition: transform .2s;
    }
    .specialty-card:hover .specialty-icon { transform: scale(1.1); }
    .specialty-name {
      font-size: 14px;
      font-weight: 700;
      color: var(--navy-dark);
      line-height: 1.3;
    }
    .specialty-desc {
      font-size: 12px;
      color: var(--text-muted);
      line-height: 1.5;
    }
    .specialty-arrow {
      width: 28px; height: 28px;
      border-radius: 50%;
      background: var(--navy);
      color: white;
      display: flex;
      align-items: center;
      justify-content: center;
      opacity: 0;
      transform: translateY(4px);
      transition: all .2s;
    }
    .specialty-arrow svg { width: 14px; height: 14px; }
    .specialty-card:hover .specialty-arrow { opacity: 1; transform: translateY(0); }

    /* Icon color themes */
    .ic-blue   { background: rgba(14,165,233,.12); }
    .ic-emerald{ background: rgba(16,185,129,.12); }
    .ic-rose   { background: rgba(244,63,94,.12); }
    .ic-violet { background: rgba(139,92,246,.12); }
    .ic-amber  { background: rgba(245,158,11,.12); }
    .ic-navy   { background: rgba(27,20,100,.08); }

    /* ═══════════════════════════════════════
       HOW IT WORKS
    ═══════════════════════════════════════ */
    .how-it-works { background: var(--off-white); }
    .hiw-header {
      text-align: center;
      margin-bottom: 60px;
    }
    .hiw-steps {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 32px;
      position: relative;
    }
    /* Connector line */
    .hiw-steps::before {
      content: '';
      position: absolute;
      top: 44px;
      left: calc(50% / 3);
      right: calc(50% / 3);
      height: 2px;
      background: linear-gradient(90deg, var(--navy) 0%, var(--yellow) 100%);
      border-radius: 2px;
    }
    .hiw-step {
      background: white;
      border-radius: var(--radius-lg);
      padding: 36px 28px;
      box-shadow: var(--shadow-sm);
      border: 1.5px solid var(--gray-100);
      transition: box-shadow .2s, transform .2s;
      position: relative;
    }
    .hiw-step:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
    .hiw-step-num {
      width: 52px; height: 52px;
      border-radius: 14px;
      background: var(--navy);
      color: white;
      font-size: 20px;
      font-weight: 800;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 24px;
      position: relative;
    }
    .hiw-step:nth-child(2) .hiw-step-num { background: var(--teal); }
    .hiw-step:nth-child(3) .hiw-step-num { background: linear-gradient(135deg, var(--navy), var(--teal)); }
    .hiw-step-badge {
      position: absolute;
      top: -8px;
      right: -8px;
      background: var(--yellow);
      width: 20px; height: 20px;
      border-radius: 50%;
      border: 2px solid white;
    }
    .hiw-step-title {
      font-size: 20px;
      font-weight: 700;
      color: var(--navy-dark);
      margin-bottom: 12px;
      letter-spacing: -.01em;
    }
    .hiw-step-desc {
      font-size: 15px;
      color: var(--text-muted);
      line-height: 1.65;
    }
    .hiw-step-icon { margin-bottom: 20px; font-size: 32px; }

    /* ═══════════════════════════════════════
       TESTIMONIALS
    ═══════════════════════════════════════ */
    .testimonials { background: white; }
    .testimonials-header {
      text-align: center;
      margin-bottom: 52px;
    }
    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }
    .testimonial-card {
      background: var(--off-white);
      border-radius: var(--radius-lg);
      padding: 32px;
      border: 1.5px solid var(--gray-100);
      transition: box-shadow .2s, transform .2s;
      position: relative;
      overflow: hidden;
    }
    .testimonial-card::before {
      content: '"';
      position: absolute;
      top: -8px;
      left: 24px;
      font-size: 120px;
      font-weight: 800;
      color: var(--navy);
      opacity: .05;
      line-height: 1;
      font-family: Georgia, serif;
    }
    .testimonial-card:hover { box-shadow: var(--shadow-md); transform: translateY(-4px); }
    .testimonial-stars {
      display: flex;
      gap: 3px;
      margin-bottom: 16px;
    }
    .star { color: var(--yellow); font-size: 16px; }
    .testimonial-text {
      font-size: 15px;
      line-height: 1.7;
      color: var(--text);
      margin-bottom: 24px;
      font-style: italic;
    }
    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .testimonial-avatar {
      width: 44px; height: 44px;
      border-radius: 50%;
      font-size: 18px;
      font-weight: 700;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }
    .av-purple { background: rgba(139,92,246,.15); color: #7c3aed; }
    .av-blue   { background: rgba(14,165,233,.15); color: #0284c7; }
    .av-teal   { background: rgba(16,185,129,.15); color: #059669; }
    .testimonial-name { font-weight: 700; font-size: 14px; color: var(--navy-dark); }
    .testimonial-loc  { font-size: 12px; color: var(--text-muted); margin-top: 2px; }

    /* ═══════════════════════════════════════
       APP PROMO
    ═══════════════════════════════════════ */
    .app-promo {
      background: linear-gradient(135deg, var(--navy-dark), var(--navy-light));
      overflow: hidden;
      position: relative;
    }
    .app-promo-bg {
      position: absolute;
      inset: 0;
      background-image: radial-gradient(circle, rgba(255,255,255,.06) 1px, transparent 1px);
      background-size: 24px 24px;
    }
    .app-promo-inner {
      position: relative;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
    }
    .app-promo-text { }
    .app-promo-label { color: var(--yellow); border-color: rgba(255,217,48,.3); background: rgba(255,217,48,.12); margin-bottom: 20px; }
    .app-promo-title {
      font-size: clamp(28px, 3.5vw, 42px);
      font-weight: 800;
      color: white;
      letter-spacing: -.03em;
      line-height: 1.15;
      margin-bottom: 16px;
    }
    .app-promo-subtitle {
      font-size: 16px;
      color: rgba(255,255,255,.72);
      line-height: 1.65;
      margin-bottom: 32px;
    }
    .app-promo-features {
      margin-bottom: 36px;
    }
    .app-feature {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 8px 0;
      font-size: 14px;
      color: rgba(255,255,255,.85);
      font-weight: 500;
    }
    .app-feature-icon {
      width: 28px; height: 28px;
      border-radius: 8px;
      background: rgba(255,217,48,.15);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 14px;
      flex-shrink: 0;
    }
    .app-buttons { display: flex; gap: 12px; flex-wrap: wrap; }
    .app-promo-visual {
      display: flex;
      justify-content: center;
      align-items: flex-end;
      position: relative;
      height: 380px;
    }
    /* Phone mockup */
    .phone-mockup {
      width: 200px;
      height: 360px;
      background: white;
      border-radius: 32px;
      box-shadow: 0 32px 80px rgba(0,0,0,.4);
      padding: 12px;
      position: relative;
      z-index: 2;
      animation: float 4s ease-in-out infinite;
    }
    .phone-screen {
      width: 100%;
      height: 100%;
      background: var(--off-white);
      border-radius: 22px;
      overflow: hidden;
      display: flex;
      flex-direction: column;
    }
    .phone-status { height: 28px; background: var(--navy-dark); display: flex; align-items: center; justify-content: center; }
    .phone-notch { width: 70px; height: 10px; background: black; border-radius: 6px; }
    .phone-content { padding: 12px 10px; flex: 1; }
    .phone-header-bar { font-size: 10px; font-weight: 700; color: var(--navy-dark); margin-bottom: 10px; }
    .phone-search-bar {
      background: white;
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 9px;
      color: var(--text-muted);
      margin-bottom: 10px;
      box-shadow: var(--shadow-sm);
      display: flex;
      align-items: center;
      gap: 6px;
    }
    .phone-mini-card {
      background: white;
      border-radius: 10px;
      padding: 8px;
      margin-bottom: 6px;
      box-shadow: var(--shadow-sm);
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .phone-mini-avatar {
      width: 28px; height: 28px;
      border-radius: 50%;
      background: rgba(27,20,100,.1);
      flex-shrink: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 12px;
    }
    .phone-mini-info { }
    .phone-mini-name { font-size: 9px; font-weight: 700; color: var(--navy-dark); }
    .phone-mini-spec { font-size: 8px; color: var(--text-muted); }
    .phone-mini-btn {
      margin-left: auto;
      background: var(--navy);
      color: white;
      font-size: 7px;
      font-weight: 700;
      padding: 3px 6px;
      border-radius: 4px;
    }
    .phone-shadow {
      position: absolute;
      bottom: -20px;
      left: 50%;
      transform: translateX(-50%);
      width: 160px;
      height: 40px;
      background: rgba(0,0,0,.3);
      filter: blur(20px);
      border-radius: 50%;
    }
    /* Second phone offset */
    .phone-mockup-2 {
      position: absolute;
      right: 20px;
      bottom: 20px;
      width: 160px;
      height: 290px;
      opacity: .55;
      z-index: 1;
      animation: float 4s 1.5s ease-in-out infinite;
    }

    /* ═══════════════════════════════════════
       FOOTER
    ═══════════════════════════════════════ */
    .footer {
      background: var(--navy-dark);
      padding: 60px 0 0;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
      gap: 40px;
      margin-bottom: 48px;
    }
    .footer-brand .logo { color: white; margin-bottom: 14px; }
    .footer-brand-desc {
      font-size: 14px;
      color: rgba(255,255,255,.55);
      line-height: 1.7;
      max-width: 260px;
      margin-bottom: 24px;
    }
    .footer-tagline {
      display: inline-block;
      background: rgba(255,217,48,.12);
      color: var(--yellow);
      font-size: 12px;
      font-weight: 700;
      padding: 6px 14px;
      border-radius: 100px;
      border: 1px solid rgba(255,217,48,.25);
    }
    .footer-col-title {
      font-size: 12px;
      font-weight: 700;
      letter-spacing: .08em;
      text-transform: uppercase;
      color: rgba(255,255,255,.45);
      margin-bottom: 18px;
    }
    .footer-links { display: flex; flex-direction: column; gap: 10px; }
    .footer-link {
      font-size: 14px;
      color: rgba(255,255,255,.65);
      font-weight: 500;
      transition: color .15s;
    }
    .footer-link:hover { color: white; }
    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,.1);
      padding: 20px 0;
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 12px;
    }
    .footer-copy {
      font-size: 13px;
      color: rgba(255,255,255,.4);
    }
    .footer-copy strong { color: var(--yellow); }
    .footer-legal { display: flex; gap: 20px; }
    .footer-legal a {
      font-size: 13px;
      color: rgba(255,255,255,.4);
      transition: color .15s;
    }
    .footer-legal a:hover { color: white; }

    /* ═══════════════════════════════════════
       SCROLL REVEAL
    ═══════════════════════════════════════ */
    .reveal {
      opacity: 0;
      transform: translateY(20px);
      transition: opacity .6s ease, transform .6s ease;
    }
    .reveal.visible {
      opacity: 1;
      transform: translateY(0);
    }
    .reveal-delay-1 { transition-delay: .1s; }
    .reveal-delay-2 { transition-delay: .2s; }
    .reveal-delay-3 { transition-delay: .3s; }
    .reveal-delay-4 { transition-delay: .4s; }
    .reveal-delay-5 { transition-delay: .5s; }
    .reveal-delay-6 { transition-delay: .6s; }

    /* ═══════════════════════════════════════
       RESPONSIVE
    ═══════════════════════════════════════ */
    @media (max-width: 1024px) {
      .specialties-grid { grid-template-columns: repeat(3, 1fr); }
      .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
      .footer-brand { grid-column: span 2; }
      .hiw-steps::before { display: none; }
      .app-promo-inner { gap: 40px; }
    }

    @media (max-width: 768px) {
      .section { padding: 60px 0; }
      .nav, .header-cta { display: none; }
      .hamburger { display: flex; }

      .search-card {
        flex-direction: column;
        border-radius: var(--radius-lg);
        gap: 2px;
        padding: 6px;
      }
      .search-field {
        border-right: none;
        border-bottom: 1px solid var(--gray-100);
      }
      .search-field:last-of-type { border-bottom: none; }
      .search-btn { width: 100%; justify-content: center; margin-top: 4px; }

      .specialties-grid { grid-template-columns: repeat(2, 1fr); }
      .hiw-steps { grid-template-columns: 1fr; }
      .testimonials-grid { grid-template-columns: 1fr; }
      .app-promo-inner { grid-template-columns: 1fr; }
      .app-promo-visual { display: none; }
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .footer-brand { grid-column: span 2; }
      .footer-bottom { flex-direction: column; align-items: flex-start; }
      .stats-inner { flex-direction: column; gap: 24px; }
      .stat-item + .stat-item::before { display: none; }

      .hero-title { font-size: 32px; }
      .hero-subtitle { font-size: 15px; }
      .hero-trust { gap: 12px; }
    }

    @media (max-width: 480px) {
      .specialties-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: 1fr; }
      .footer-brand { grid-column: span 1; }
      .app-buttons { flex-direction: column; }
    }
  </style>
</head>
<body>

<!-- ══════════════════════════════════════ HEADER -->
<header class="header">
  <div class="container">
    <div class="header-inner">
      <a href="/" class="logo" aria-label="MedBook Home">
        <div class="logo-mark" aria-hidden="true">
          <svg viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M10 3v14M3 10h14" stroke="#FFD930" stroke-width="2.5" stroke-linecap="round"/>
          </svg>
        </div>
        Med<span class="logo-dot">Book</span>
      </a>

      <nav class="nav" aria-label="Main navigation">
        <a class="nav-link" href="#specialties">Browse</a>
        <a class="nav-link" href="#">Help</a>
      </nav>

      <div class="header-cta">
        <a class="btn btn-secondary btn-sm" href="#">Log In</a>
        <a class="btn btn-navy btn-sm" href="#">Sign Up</a>
      </div>

      <button class="hamburger" id="hamburgerBtn" aria-label="Open menu" aria-expanded="false">
        <span></span><span></span><span></span>
      </button>
    </div>
  </div>
</header>

<!-- Mobile Drawer -->
<div class="mobile-drawer" id="mobileDrawer" role="dialog" aria-modal="true" aria-label="Navigation menu">
  <div class="drawer-overlay" id="drawerOverlay"></div>
  <div class="drawer-panel">
    <div class="drawer-header">
      <a href="/" class="logo" style="font-size:18px;">
        <div class="logo-mark" style="width:30px;height:30px;">
          <svg viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M10 3v14M3 10h14" stroke="#FFD930" stroke-width="2.5" stroke-linecap="round"/>
          </svg>
        </div>
        Med<span class="logo-dot">Book</span>
